ACCOUNT_ID = "de1c262b-17d4-415c-bb1f-c49db0342d25"

async def test_connection():
    api = MetaApi(TOKEN)
    account = await api.metatrader_account_api.get_account(ACCOUNT_ID)
    
    print(f"Connexion au compte : {account.name}")
    print(f"Serveur : {account.server}")
    print(f"Statut : {account.state}")

    # Attendre que le compte soit connecté
    if account.state != 'DEPLOYED':
        print("Déploiement du compte...")
        await account.deploy()
        
    connection = account.get_rpc_connection()
    await connection.connect()
    await connection.wait_synchronized()

    # Récupérer les informations du compte
    account_information = await connection.get_account_information()
    print("Informations du compte :", account_information)

asyncio.run(test_connection())
